    data = sys.stdin.buffer.read().split(b'\n')
    groups = {}
    for line in data[1:]:
        if not line:
            continue
        parts = line.rstrip(b'\r').split(b',')
        if len(parts) < 3:
            continue
        cat = parts[1]
        v = float(parts[2])
        g = groups.get(cat)
