import sys
import math


def main():
    lines = sys.stdin.buffer.read().split(b'\n')
    groups = {}
    get = groups.get
    for line in lines[1:]:
        if not line:
            continue
        _, cat, val = line.rstrip(b'\r').split(b',', 2)
        g = get(cat)
        if g is None:
            groups[cat] = g = []
        g.append(float(val))
    out = []
    for cat in sorted(groups):
        out.append(cat.decode() + ',%.2f' % math.fsum(groups[cat]))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    main()
